<?php
namespace App\Models;
use App\Models\Concerns\HasUuid; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\HasOne; use Illuminate\Database\Eloquent\SoftDeletes;
class VoiceReport extends Model { use HasUuid, SoftDeletes; protected $fillable=['discord_guild_id','discord_channel_id','voice_session_id','reported_user_discord_id','reporter_user_discord_id','reason','comment','status','reported_at']; protected function casts(): array{return ['reported_at'=>'datetime'];} protected static function booted(): void {static::deleting(function(VoiceReport $report): void {if($report->isForceDeleting())$report->recording?->delete();});} public function guild(): BelongsTo{return $this->belongsTo(DiscordGuild::class,'discord_guild_id');} public function channel(): BelongsTo{return $this->belongsTo(DiscordChannel::class,'discord_channel_id');} public function session(): BelongsTo{return $this->belongsTo(VoiceSession::class,'voice_session_id');} public function actions(): HasMany{return $this->hasMany(ModerationAction::class);} public function recording(): HasOne{return $this->hasOne(VoiceRecording::class);} public function audioClips(): HasMany{return $this->hasMany(VoiceAudioClip::class);} public function transcripts(): HasMany{return $this->hasMany(VoiceTranscript::class);} public function reportedUserName(): string{return $this->memberName($this->reported_user_discord_id);} public function reporterUserName(): string{return $this->memberName($this->reporter_user_discord_id);} private function memberName(?string $discordId): string {return $discordId ? (DiscordMember::query()->where('discord_guild_id',$this->discord_guild_id)->where('discord_id',$discordId)->value('display_name') ?: $discordId) : 'Utilisateur inconnu';} }
